parameters.jsCode:
const auth = $input.first().json.headers?.authorization || '';
if (!auth.startsWith('Bearer ')) return [{ json: { _error: 'AUTH_MISSING_TOKEN', _status: 401 } }];
const token = auth.slice(7);
try {
  const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString('utf8'));
  if (!payload.sub) throw new Error('No sub');
  if (payload.exp && Date.now()/1000 > payload.exp) throw new Error('JWT expired');
  if (!payload.tenant_id) throw new Error('No tenant_id');
  const role = payload.role || 'architect';
  if (!['architect','super_admin'].includes(role)) return [{ json: { _error: 'FORBIDDEN', _status: 403 } }];
  const body = $input.first().json.body || {};
  const incidentId = (body.incident_id || '').trim();
  const idx = body.selected_option_index;
  const action = (body.action || '').trim();
  if (!incidentId) return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: 'incident_id requerido' } }];
  if (idx !== 0 && idx !== 1) return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: 'selected_option_index debe ser 0 o 1' } }];
  if (!['communicate','reject'].includes(action)) return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: "action debe ser 'communicate' o 'reject'" } }];
  return [{ json: {
    user_id: payload.sub,
    tenant_id: payload.tenant_id,
    role,
    incident_id: incidentId,
    selected_option_index: idx,
    action,
    custom_message: (body.custom_message || '').slice(0, 2000),
    email_override: (body.email_override || '').trim(),
    request_id: 'req_' + Math.random().toString(36).slice(2, 10)
  }}];
} catch (e) {
  return [{ json: { _error: 'AUTH_INVALID_TOKEN', _status: 401, _details: e.message } }];
}

