const r = $input.first()?.json;
const sess = $('Decode JWT + Body').first().json;
if (!r || !r.id) return [{ json: { _error: 'INCIDENT_NOT_FOUND', _status: 404, _details: 'incident_id no existe o sin acceso por RLS' } }];
if (!['proposed','detected'].includes(r.status)) {
  return [{ json: { _error: 'INVALID_STATE', _status: 409, _details: 'incident ya esta en estado ' + r.status + ', no se puede modificar' } }];
}
let options = [];
try { options = typeof r.options === 'string' ? JSON.parse(r.options) : (r.options || []); } catch (e) {}
if (!options[sess.selected_option_index]) return [{ json: { _error: 'OPTION_NOT_FOUND', _status: 400, _details: 'selected_option_index sin opcion en BD' } }];
const opt = options[sess.selected_option_index];
const toEmail = sess.email_override || r.client_email;
if (sess.action === 'communicate' && (!toEmail || !toEmail.includes('@'))) {
  return [{ json: { _error: 'NO_CLIENT_EMAIL', _status: 400, _details: 'cliente sin email, usa email_override' } }];
}
return [{ json: {
  _branch: sess.action, ...sess,
  incident_id: r.id, project_id: r.project_id,
  project_name: r.project_name, location_city: r.location_city,
  description: r.description, location: r.location, severity: r.severity,
  causa_probable: r.causa_probable, all_options: options,
  selected_option: opt,
  cost_delta_eur: Number(opt.coste_eur) || 0,
  time_delta_days: Math.round(Number(opt.dias) || 0),
  client_communication_draft: sess.custom_message || r.client_communication_draft,
  client_name: r.client_name, client_email: toEmail
}}];

